window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0493ad70565dd369"]={"versions": [{"id": "FIG-0493ad70565dd369", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Dekompositionsdiagramm der AUTOSAR-Adaptive-Methodik (SPEM-/UML-basiert). Das Diagramm stellt die hierarchische Schachtelung („nesting“) der übergeordneten Verbundaktivität „Develop Adaptive Software“ in ihre untergeordneten Prozessschritte dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Develop Adaptive Software</strong>: Übergeordnete Aktivität (Compound Activity / Task), dargestellt als Symbolkombination aus Ellipse, Akte/Dokument und Blockpfeil in einer abgerundeten Box.</li>\n<li><strong>Develop Adaptive [Application]</strong>: Erste untergeordnete Aktivität zur anwendungsbezogenen Entwicklung, verbunden über eine Komposition/Aggregation mit dem Stereotyp <code>«nesting»</code> (weiße Raute an der Elternaktivität).</li>\n<li><strong>Develop Platform-lev[el Software]</strong>: Zweite untergeordnete Aktivität zur plattformbezogenen Softwareentwicklung, aggregiert über <code>«nesting»</code>.</li>\n<li>Die Verbindungen tragen keine explizite Multiplizitätsangabe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keine zeitliche Reihenfolge oder Steuerflüsse ab, sondern eine strukturelle Dekomposition. Die Aktivität „Develop Adaptive Software“ gliedert sich logisch in die Entwicklung von Applikationen und plattformnaher Software.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die methodische Zerlegung definiert die beiden Entwicklungszweige der Adaptive Platform. Entwickler und Tool-Hersteller müssen Workflows und Rollen entsprechend in anwendungsspezifische und plattformnahe Artefakterstellung unterteilen. Da Multiplizitäten unbestimmt sind, ist die formale Kardinalität der Teilaktivitäten nicht normiert.</p>"}, {"id": "FIG-f4ab34130cb5d925", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Dekompositionsdiagramm der AUTOSAR-Adaptive-Methodik (SPEM-/UML-basiert). Das Diagramm stellt die hierarchische Schachtelung („nesting“) der übergeordneten Verbundaktivität „Develop Adaptive Software“ in ihre untergeordneten Prozessschritte dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Develop Adaptive Software</strong>: Übergeordnete Aktivität, dargestellt als zusammengesetztes SPEM-Aktivitätssymbol in einer abgerundeten Box.</li>\n<li><strong>Develop Adaptive [Application]</strong>: Erste untergeordnete Teilaktivität, verbunden über eine Aggregationsbeziehung <code>«nesting»</code> mit expliziter Multiplizität <code>0..1</code> an der Kindseite.</li>\n<li><strong>Develop Platform-lev[el Software]</strong>: Zweite untergeordnete Teilaktivität, verbunden über eine Aggregationsbeziehung <code>«nesting»</code> mit expliziter Multiplizität <code>0..1</code> an der Kindseite.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keine zeitliche Reihenfolge oder Steuerflüsse ab, sondern eine strukturelle Dekomposition. Die Aktivität „Develop Adaptive Software“ gliedert sich logisch in die Entwicklung von Applikationen und plattformnaher Software.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die explizite Multiplizität <code>0..1</code> an beiden Teilaktivitäten normiert, dass im Rahmen der übergeordneten Methodikaktivität „Develop Adaptive Software“ die Entwicklung von Applikationen und die Entwicklung plattformnaher Software jeweils optional bzw. maximal einfach durchlaufen werden können. Die Workflow-Modellierung muss somit isolierte Applikations- oder Plattform-Entwicklungsszenarien unterstützen.</p>"}, {"id": "FIG-b918921bcf131d4a", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Dekompositionsdiagramm der AUTOSAR-Adaptive-Methodik (SPEM-/UML-basiert). Das Diagramm stellt die hierarchische Schachtelung („nesting“) der übergeordneten Verbundaktivität „Develop Adaptive Software“ in ihre untergeordneten Prozessschritte dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Develop Adaptive Software</strong>: Übergeordnete Aktivität (Compound Activity).</li>\n<li><strong>Develop Adaptive [Application]</strong>: Erste untergeordnete Aktivität, eingebunden über eine <code>«nesting»</code>-Aggregation mit Multiplizität <code>0..1</code>.</li>\n<li><strong>Develop Adaptive Pla[tform-level Software]</strong>: Zweite untergeordnete Aktivität, eingebunden über eine <code>«nesting»</code>-Aggregation mit Multiplizität <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keine zeitliche Reihenfolge oder Steuerflüsse ab, sondern eine strukturelle Dekomposition. Die Aktivität „Develop Adaptive Software“ gliedert sich logisch in die Entwicklung von Applikationen und plattformnaher Software.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die explizite Multiplizität <code>0..1</code> an beiden Teilaktivitäten normiert, dass im Rahmen der übergeordneten Methodikaktivität „Develop Adaptive Software“ die Entwicklung von Applikationen und die Entwicklung plattformnaher Software jeweils optional bzw. maximal einfach durchlaufen werden können. Die Workflow-Modellierung muss somit isolierte Applikations- oder Plattform-Entwicklungsszenarien unterstützen.</p>"}, {"id": "FIG-a69bb5bd625f0768", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur-, Dekompositions- und Datenflussdiagramm der AUTOSAR-Adaptive-Methodik. Neben der hierarchischen Aufgabenzerlegung („nesting“) stellt das Diagramm die Erzeugung des primären Ergebnis-Artefakts über eine Ausgabebeziehung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Develop Adaptive Software</strong>: Übergeordnete Aktivität (Compound Activity).</li>\n<li><strong>Develop Adaptive Application</strong>: Vollständig beschriftete untergeordnete Aktivität für Applikationen, angebunden über <code>«nesting»</code> mit Multiplizität <code>0..1</code>.</li>\n<li><strong>Develop Adaptive Platform-</strong>: Untergeordnete Aktivität für Plattformsoftware (mit Umbruch-Bindestrich), angebunden über <code>«nesting»</code> mit Multiplizität <code>0..1</code>.</li>\n<li><strong>Adaptive Software</strong>: Deliverable- bzw. Work-Product-Artefakt, dargestellt als Briefumschlag mit gestricheltem Ein-/Ausgabe-Port links.</li>\n<li><strong>«output»</strong>: Gerichtete Datenflusskante von „Develop Adaptive Software“ zum Artefakt „Adaptive Software“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die übergeordnete Aktivität „Develop Adaptive Software“ führt bei ihrer Ausführung zur Generierung des zusammenfassenden Artefakts „Adaptive Software“. Innerhalb der Aktivität erfolgt die Dekomposition strukturell in die beiden optionalen Teilprozesse <code>0..1</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Definition des Liefergegenstands: Jeder Durchlauf von „Develop Adaptive Software“ liefert als formales Endergebnis das Gesamt-Artefakt „Adaptive Software“ (<code>«output»</code>). Entwicklungswerkzeuge und Prozess-Pipelines müssen sicherstellen, dass die Aggregation der Applikations- und Plattform-Artefakte dieses Zielprodukt konsistent erzeugt.</p>"}, {"id": "FIG-e58a2cb0cca4f5d1", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur-, Dekompositions- und Datenflussdiagramm der AUTOSAR-Adaptive-Methodik. Neben der hierarchischen Aufgabenzerlegung („nesting“) stellt das Diagramm die Erzeugung des primären Ergebnis-Artefakts über eine Ausgabebeziehung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Develop Adaptive Software</strong>: Übergeordnete Aktivität (Compound Activity).</li>\n<li><strong>Develop Adaptive Application</strong>: Vollständig beschriftete untergeordnete Aktivität für Applikationen, angebunden über <code>«nesting»</code> mit Multiplizität <code>0..1</code>.</li>\n<li><strong>Develop Adaptive Platform-</strong>: Untergeordnete Aktivität für Plattformsoftware (mit Umbruch-Bindestrich), angebunden über <code>«nesting»</code> mit Multiplizität <code>0..1</code>.</li>\n<li><strong>Adaptive Software</strong>: Deliverable- bzw. Work-Product-Artefakt, dargestellt als Briefumschlag mit gestricheltem Ein-/Ausgabe-Port links.</li>\n<li><strong>«output»</strong>: Gerichtete Datenflusskante von „Develop Adaptive Software“ zum Artefakt „Adaptive Software“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die übergeordnete Aktivität „Develop Adaptive Software“ führt bei ihrer Ausführung zur Generierung des zusammenfassenden Artefakts „Adaptive Software“. Innerhalb der Aktivität erfolgt die Dekomposition strukturell in die beiden optionalen Teilprozesse <code>0..1</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Definition des Liefergegenstands: Jeder Durchlauf von „Develop Adaptive Software“ liefert als formales Endergebnis das Gesamt-Artefakt „Adaptive Software“ (<code>«output»</code>). Entwicklungswerkzeuge und Prozess-Pipelines müssen sicherstellen, dass die Aggregation der Applikations- und Plattform-Artefakte dieses Zielprodukt konsistent erzeugt.</p>"}], "trans": [{"from": "FIG-0493ad70565dd369", "to": "FIG-f4ab34130cb5d925", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung der Kardinalitäten <code>0..1</code> an beiden Kind-Aktivitäten der Aggregationen (<code>«nesting»</code>).</li>\n</ul>"}, {"from": "FIG-f4ab34130cb5d925", "to": "FIG-b918921bcf131d4a", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Umbenennung der rechten Teilaktivität von „Develop Platform-level Software“ (abgeschnitten als „Develop Platform-lev...“) zu „Develop Adaptive Platform-level Software“ (abgeschnitten als „Develop Adaptive Pla...“).</li>\n</ul>"}, {"from": "FIG-b918921bcf131d4a", "to": "FIG-a69bb5bd625f0768", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung des Ausgabe-Artefakts „Adaptive Software“ (Briefumschlag-Symbol mit Port/Interface-Markierung).</li>\n<li>Ergänzung der gerichteten Beziehung <code>«output»</code> von der Verbundaktivität „Develop Adaptive Software“ zum Artefakt „Adaptive Software“.</li>\n<li>Vollständige Ausschreibung der Bezeichner unter den Kind-Aktivitäten zu „Develop Adaptive Application“ und „Develop Adaptive Platform-“ (letzteres mit Trennstrich umbrochen).</li>\n</ul>"}, {"from": "FIG-a69bb5bd625f0768", "to": "FIG-e58a2cb0cca4f5d1", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
